import{_ as t,c as i,o as a,ae as n}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"DEPLOYING ADVANCED NUCLEAR REACTOR TECHNOLOGIES FOR NATIONAL SECURITY","description":"","frontmatter":{"title":"DEPLOYING ADVANCED NUCLEAR REACTOR TECHNOLOGIES FOR NATIONAL SECURITY","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/05/deploying-advanced-nuclear-reactor-technologies-for-national-security/","publishDate":"2025-05-23T18:00:00-04:00"},"headers":[],"relativePath":"executive-orders/2025-05-23-deploying-advanced-nuclear-reactor-technologies-for-national-security.md","filePath":"executive-orders/2025-05-23-deploying-advanced-nuclear-reactor-technologies-for-national-security.md"}'),r={name:"executive-orders/2025-05-23-deploying-advanced-nuclear-reactor-technologies-for-national-security.md"};function o(l,e,s,c,d,u){return a(),i("div",null,e[0]||(e[0]=[n('<h1 id="deploying-advanced-nuclear-reactor-technologies-for-national-security" tabindex="-1">DEPLOYING ADVANCED NUCLEAR REACTOR TECHNOLOGIES FOR NATIONAL SECURITY <a class="header-anchor" href="#deploying-advanced-nuclear-reactor-technologies-for-national-security" aria-label="Permalink to &quot;DEPLOYING ADVANCED NUCLEAR REACTOR TECHNOLOGIES FOR NATIONAL SECURITY&quot;">​</a></h1><p>Published: Friday, May 23, 2025</p><ul><li><p>The United States has a national security imperative to ensure a secure and reliable energy supply for critical defense facilities, especially concerning advanced computing infrastructure for AI and other mission capabilities.</p></li><li><p>Vulnerabilities in energy supply pose strategic risks, necessitating the rapid development of advanced nuclear reactors (e.g., Generation III+, small modular reactors, and microreactors) to support these needs.</p></li><li><p>The Federal Government is tasked with accelerating the development, demonstration, deployment, and export of advanced nuclear technologies.</p></li><li><p><strong>Policy Objectives:</strong></p><ul><li>Rapid development and deployment of advanced nuclear technologies for critical infrastructure.</li><li>Enable private sector investment in advanced nuclear technologies by aligning federal incentives.</li><li>Coordinate regulatory efforts between the Department of Defense (DoD) and the Department of Energy (DOE).</li></ul></li><li><p><strong>Action Steps:</strong></p><ul><li>The Secretary of Defense will establish a nuclear energy program and commence the operation of a nuclear reactor by September 30, 2028.</li><li>The Secretary of Energy will provide technical support for advanced nuclear reactors at military installations.</li><li>A 240-day timeline for recommending legislative proposals and regulatory actions regarding advanced nuclear reactors on military sites.</li></ul></li><li><p>The Secretary of Energy will:</p><ul><li>Designate AI data centers in coordination with DOE as critical defense facilities.</li><li>Identify Department of Energy sites for advanced nuclear technology deployment within 90 days.</li><li>Ensure legal processes for the siting and operation of advanced reactor technologies at DOE sites.</li></ul></li><li><p><strong>Fuel Supply Initiatives:</strong></p><ul><li>Identify and process useful uranium and plutonium material for domestic reactor fuel.</li><li>Release at least 20 metric tons of high assay low-enriched uranium (HALEU) for private sector projects.</li><li>Facilitate the establishment of domestic nuclear fuel fabrication and supply chains.</li></ul></li><li><p><strong>Support for Implementation:</strong></p><ul><li>The DoD and DOE will use various authorities to support contracts necessary for the integration of nuclear technologies at installations.</li><li>Consultation with the Council on Environmental Quality for regulatory streamlining and categorical exclusions related to nuclear projects.</li></ul></li><li><p><strong>International Cooperation:</strong></p><ul><li>The Secretary of State will lead diplomatic efforts to establish new nuclear cooperation agreements and renegotiate existing ones to enhance market access for the U.S. nuclear industry.</li><li>Strategies to enhance global competitiveness of U.S. nuclear technology suppliers will be developed within 90 days.</li></ul></li><li><p><strong>Security and Compliance:</strong></p><ul><li>The Secretary of Defense will prioritize security clearances for personnel to facilitate the use of nuclear technologies.</li><li>The order will be executed in line with existing budget and legislative processes.</li></ul></li><li><p><strong>Legal and Procedural Considerations:</strong></p><ul><li>The order does not create enforceable rights or benefits and will be implemented in compliance with legal and safety standards.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/05/deploying-advanced-nuclear-reactor-technologies-for-national-security/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/05/deploying-advanced-nuclear-reactor-technologies-for-national-security/</a></p>',4)]))}const h=t(r,[["render",o]]);export{g as __pageData,h as default};
